<?php $maxNet=max(1,...array_map(static fn($m)=>abs((float)$m['net']),$monthly)); ?>
<div class="page-heading"><div><span class="eyebrow">Direction financière</span><h1>Finances</h1><p>Revenus, dépenses et masse salariale du club.</p></div></div>
<div class="finance-metrics"><section class="panel metric-card"><span>Solde actuel</span><strong><?= format_money($club['balance']) ?></strong><small>Trésorerie disponible</small></section><section class="panel metric-card"><span>Revenus saison</span><strong class="text-success"><?= format_money($totals['income']) ?></strong><small>Billetterie, sponsors, TV, ventes</small></section><section class="panel metric-card"><span>Dépenses saison</span><strong class="text-danger"><?= format_money($totals['expense']) ?></strong><small>Salaires, achats, fonctionnement</small></section><section class="panel metric-card"><span>Salaires joueurs / sem.</span><strong><?= format_money($weeklyWages) ?></strong><small>Budget : <?= format_money($club['wage_budget']) ?></small></section></div>
<div class="finance-grid"><section class="panel"><div class="panel__header"><h2>Flux net mensuel</h2></div><div class="panel__body finance-chart"><?php if(!$monthly): ?><p class="muted">Les premières opérations apparaîtront en avançant dans le temps.</p><?php endif; ?><?php foreach($monthly as $month): ?><div><time><?= e($month['month']) ?></time><span class="finance-chart__bar"><i class="<?= $month['net']>=0?'positive':'negative' ?>" style="width:<?= round(abs((float)$month['net'])*100/$maxNet) ?>%"></i></span><strong><?= $month['net']>=0?'+':'' ?><?= format_money($month['net']) ?></strong></div><?php endforeach; ?></div></section><section class="panel"><div class="panel__header"><h2>Structure du budget</h2></div><div class="panel__body"><dl class="facts"><div><dt>Budget transferts restant</dt><dd><?= format_money($club['transfer_budget']) ?></dd></div><div><dt>Budget salarial hebdomadaire</dt><dd><?= format_money($club['wage_budget']) ?></dd></div><div><dt>Résultat net de la saison</dt><dd><?= format_money((float)$totals['income']-(float)$totals['expense']) ?></dd></div><div><dt>Confiance de la direction</dt><dd><?= (int)$club['board_confidence'] ?>%</dd></div></dl><div class="progress"><span style="width:<?= (int)$club['board_confidence'] ?>%"></span></div></div></section></div>
<section class="panel"><div class="panel__header"><h2>Livre de comptes</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Catégorie</th><th>Description</th><th>Revenu</th><th>Dépense</th></tr></thead><tbody><?php foreach($ledger as $entry): ?><tr><td><?= format_date($entry['occurred_on']) ?></td><td><span class="badge"><?= e($entry['category']) ?></span></td><td><?= e($entry['description']) ?></td><td class="text-success"><?= $entry['direction']==='income'?'+'.format_money($entry['amount']):'—' ?></td><td class="text-danger"><?= $entry['direction']==='expense'?'-'.format_money($entry['amount']):'—' ?></td></tr><?php endforeach; ?><?php if(!$ledger): ?><tr><td colspan="5">Aucune opération comptable pour le moment.</td></tr><?php endif; ?></tbody></table></div></section>
